def _sync_new_sequences(apps, schema_editor):
    """Sync Id sequences for the newly-portable write tables (bulk-migrated
    data loaded explicit Ids, so ORM creates would otherwise reuse Ids)."""
    mapping = {
        "bss_legacy_rtl_chatbot": "Id",
        "bss_legacy_dbo_clientactmapping": "Id",
        "bss_legacy_dbo_tblcdmmaster": "Id",
        "bss_legacy_dbo_timeperiod": "Id",
        "bss_legacy_dbo_userpasswordhistory": "Id",
        "bss_legacy_dbo_paymentrequestlog": "Id",
        "bss_legacy_dbo_conversation": "Id",
        "bss_legacy_dbo_mapping": "Id",
        "bss_legacy_dbo_location": "Id",
        "bss_legacy_evm_tbl_sitemanager": "SiteId",
    }
    with schema_editor.connection.cursor() as cursor:
        for table, col in mapping.items():
            seq = f"{table}_{col}_seq"
            sql = 'SELECT setval(\'"%s"\', (SELECT COALESCE(max("%s"), 1) FROM "%s"))' % (seq, col, table)
            cursor.execute(sql)

